import PaperBroker from "./brokers/PaperBroker";
import type BrokerClient from "./brokers/BrokerClient";
import ZerodhaBroker from "./brokers/ZerodhaBroker";
import AngelOneBroker from "./brokers/AngelOneBroker";
import env from "./config/env";
import { getPortfolioRepository, getSettingsRepository, getStopLossRepository, getAuditLogRepository } from "./persistence";
import MarketDataService from "./services/MarketDataService";
import PortfolioService from "./services/PortfolioService";
import TradingEngine from "./services/TradingEngine";
import HistoricalDataService from "./services/HistoricalDataService";
import PortfolioRebalancer from "./services/PortfolioRebalancer";
import ExecutionPlanner from "./services/ExecutionPlanner";
import AngelOneHistoricalProvider from "./providers/AngelOneHistoricalProvider";
import VWAPStrategy from "./strategies/VWAPStrategy";
import type { TickerClient } from "./services/TickerClient";
import AngelOneTickerService from "./services/AngelOneTickerService";
import ReconciliationService from "./services/ReconciliationService";
import { RiskManager } from "./services/RiskManager";
import { StopLossMonitor } from "./services/StopLossMonitor";
import { AuditLogService } from "./services/AuditLogService";
import { HealthService } from "./services/HealthService";
import { NotificationService } from "./services/NotificationService";
import { TunnelService } from "./services/TunnelService";
import { DiscordBotService } from "./services/DiscordBotService";
import type { SettingsRepository } from "./persistence/SettingsRepository";
import type { StopLossRepository } from "./persistence/StopLossRepository";
import type { AuditLogRepository } from "./persistence/AuditLogRepository";

export interface AppContainer {
  portfolioService: PortfolioService;
  marketDataService: MarketDataService;
  historicalDataService: HistoricalDataService;
  portfolioRebalancer: PortfolioRebalancer;
  executionPlanner: ExecutionPlanner;
  brokerClient: BrokerClient;
  tradingEngine: TradingEngine;
  tickerClient: TickerClient | null;
  reconciliationService: ReconciliationService;
  settingsRepository: SettingsRepository;
  stopLossRepository: StopLossRepository;
  auditLogRepository: AuditLogRepository;
  riskManager: RiskManager;
  stopLossMonitor: StopLossMonitor;
  auditLogService: AuditLogService;
  healthService: HealthService;
  notificationService: NotificationService;
  tunnelService: TunnelService;
  discordBotService: DiscordBotService;
}

const buildBroker = (): BrokerClient => {
  switch (env.brokerProvider) {
    case "zerodha":
      return new ZerodhaBroker({
        apiKey: env.brokerApiKey,
        apiSecret: env.brokerApiSecret,
        accessToken: env.brokerAccessToken || process.env.ZERODHA_ACCESS_TOKEN,
        requestToken: env.brokerRequestToken,
        defaultExchange: env.brokerDefaultExchange,
        product: env.brokerProduct,
      });
    case "angelone":
      return new AngelOneBroker({
        apiKey: env.angelOneApiKey,
        clientId: env.angelOneClientId,
        password: env.angelOnePassword,
        totpSecret: env.angelOneTotpSecret,
        defaultExchange: env.angelOneDefaultExchange,
        productType: env.angelOneProductType,
      });
    default:
      return new PaperBroker();
  }
};

const buildHistoricalDataService = (): HistoricalDataService => {
  // Use Angel One provider if broker is set to angelone
  if (env.brokerProvider === "angelone" && env.angelOneApiKey) {
    const provider = new AngelOneHistoricalProvider({
      apiKey: env.angelOneApiKey,
      clientId: env.angelOneClientId,
      password: env.angelOnePassword,
      totpSecret: env.angelOneTotpSecret,
    });
    return new HistoricalDataService(undefined, provider);
  }

  // Default to mock provider
  return new HistoricalDataService();
};

/**
 * Build ticker service based on DATA_PROVIDER config
 * Uses Angel One's free WebSocket ticker for real-time market data
 */
const buildTicker = (marketData: MarketDataService): TickerClient | null => {
  // Use Angel One ticker if data provider is set to angelone
  if (env.dataProvider === "angelone" && env.angelOneApiKey) {
    return new AngelOneTickerService(marketData);
  }
  return null;
};

export const createContainer = (): AppContainer => {
  const portfolioService = new PortfolioService(getPortfolioRepository());
  const settingsRepository = getSettingsRepository();
  const stopLossRepository = getStopLossRepository();
  const marketDataService = new MarketDataService();
  const historicalDataService = buildHistoricalDataService();
  const portfolioRebalancer = new PortfolioRebalancer();
  const executionPlanner = new ExecutionPlanner();
  const brokerClient = buildBroker();
  const riskManager = new RiskManager(settingsRepository);
  const tradingEngine = new TradingEngine({
    broker: brokerClient,
    marketData: marketDataService,
    portfolioService,
    riskManager,
  });

  tradingEngine.registerStrategy(new VWAPStrategy());

  // Build ticker for real-time market data (uses DATA_PROVIDER config)
  const tickerClient = buildTicker(marketDataService);

  // Build reconciliation service for syncing with broker
  const reconciliationService = new ReconciliationService(brokerClient, portfolioService);

  // Build stop-loss monitor
  const stopLossMonitor = new StopLossMonitor({
    marketDataService,
    tradingEngine,
    stopLossRepository,
    riskManager,
  });

  // Build audit log service
  const auditLogRepository = getAuditLogRepository();
  const auditLogService = new AuditLogService({
    repository: auditLogRepository,
    tradingEngine,
    stopLossMonitor,
    settingsRepository,
  });

  // Build health service
  const healthService = new HealthService({
    brokerClient,
    tickerClient: tickerClient || undefined,
    marketDataService,
    stopLossMonitor,
  });

  // Build notification service (only if webhook configured)
  const notificationService = new NotificationService({
    discordWebhookUrl: env.discordWebhookUrl,
    webhookUrl: env.webhookUrl,
    tradingEngine,
    stopLossMonitor,
  });

  // Wire RiskManager critical errors to notifications
  riskManager.on("critical_error", (event: { type: string; error: Error }) => {
    void notificationService.notifyCriticalError(
      event.type,
      event.error?.message || "Unknown error"
    );
  });

  // Build remote access services
  const tunnelService = new TunnelService();

  const discordBotService = new DiscordBotService({
    token: env.discordBotToken,
    tunnelService,
  });

  return {
    portfolioService,
    marketDataService,
    historicalDataService,
    portfolioRebalancer,
    executionPlanner,
    brokerClient,
    tradingEngine,
    tickerClient,
    reconciliationService,
    settingsRepository,
    stopLossRepository,
    auditLogRepository,
    riskManager,
    stopLossMonitor,
    auditLogService,
    healthService,
    notificationService,
    tunnelService,
    discordBotService,
  };
};

let activeContainer: AppContainer | null = null;

export const getContainer = (): AppContainer => {
  if (!activeContainer) {
    activeContainer = createContainer();
  }

  return activeContainer;
};

export const resetContainer = (): AppContainer => {
  activeContainer = createContainer();
  return activeContainer;
};

// For testing purposes
export const setContainer = (container: AppContainer): void => {
  activeContainer = container;
};

export const resolvePortfolioService = (): PortfolioService => getContainer().portfolioService;

export const resolveMarketDataService = (): MarketDataService => getContainer().marketDataService;

export const resolveHistoricalDataService = (): HistoricalDataService => getContainer().historicalDataService;

export const resolvePortfolioRebalancer = (): PortfolioRebalancer => getContainer().portfolioRebalancer;

export const resolveExecutionPlanner = (): ExecutionPlanner => getContainer().executionPlanner;

export const resolveBrokerClient = (): BrokerClient => getContainer().brokerClient;

export const resolveTradingEngine = (): TradingEngine => getContainer().tradingEngine;

export const resolveTickerClient = (): TickerClient | null => getContainer().tickerClient;

export const resolveReconciliationService = (): ReconciliationService => getContainer().reconciliationService;

export const resolveSettingsRepository = (): SettingsRepository => getContainer().settingsRepository;

export const resolveStopLossRepository = (): StopLossRepository => getContainer().stopLossRepository;

export const resolveAuditLogRepository = (): AuditLogRepository => getContainer().auditLogRepository;

export const resolveRiskManager = (): RiskManager => getContainer().riskManager;

export const resolveStopLossMonitor = (): StopLossMonitor => getContainer().stopLossMonitor;

export const resolveAuditLogService = (): AuditLogService => getContainer().auditLogService;

export const resolveHealthService = (): HealthService => getContainer().healthService;

export const resolveNotificationService = (): NotificationService => getContainer().notificationService;

export const resolveDiscordBotService = (): DiscordBotService => getContainer().discordBotService;

import { randomUUID } from "crypto";
import { HttpError } from "../utils/HttpError";
import type {
  PortfolioPositionSnapshot,
  PortfolioSnapshot,
  Stock,
  Trade,
  TradeSide,
  TradeSummary,
} from "../types";
import type {
  CreateStockRecord,
  CreateTradeRecord,
  PortfolioRepository,
} from "../persistence/PortfolioRepository";
import { RepositoryConflictError } from "../persistence/errors";

export interface CreateStockInput {
  symbol: string;
  name: string;
}

export interface CreateTradeInput {
  symbol: string;
  side: TradeSide;
  quantity: number;
  price: number;
  executedAt?: Date;
  notes?: string;
}

interface PositionState {
  netQuantity: number;
  totalCost: number;
  realizedPnl: number;
}

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export class PortfolioService {
  constructor(private readonly repository: PortfolioRepository) { }

  public async addStock(input: CreateStockInput): Promise<Stock> {
    const symbol = input.symbol.trim().toUpperCase();
    if (!symbol) {
      throw new HttpError(400, "Stock symbol is required");
    }

    const name = input.name.trim();
    if (!name) {
      throw new HttpError(400, "Stock name is required");
    }

    const record: CreateStockRecord = {
      symbol,
      name,
      createdAt: new Date(),
    };

    try {
      return await this.repository.createStock(record);
    } catch (error) {
      if (error instanceof RepositoryConflictError) {
        throw new HttpError(409, `Stock with symbol ${symbol} already exists`);
      }
      throw error;
    }
  }

  public async listStocks(): Promise<Stock[]> {
    return this.repository.listStocks();
  }

  public async addTrade(input: CreateTradeInput): Promise<Trade> {
    const symbol = input.symbol.trim().toUpperCase();
    if (!symbol) {
      throw new HttpError(400, "Trade symbol is required");
    }

    const stock = await this.repository.findStock(symbol);
    if (!stock) {
      throw new HttpError(404, `Unknown stock symbol ${symbol}`);
    }

    if (!Number.isFinite(input.quantity) || input.quantity <= 0) {
      throw new HttpError(400, "Trade quantity must be a positive number");
    }

    if (!Number.isFinite(input.price) || input.price <= 0) {
      throw new HttpError(400, "Trade price must be a positive number");
    }

    const record: CreateTradeRecord = {
      id: randomUUID(),
      symbol,
      side: input.side,
      quantity: Math.round(input.quantity),
      price: Number(input.price),
      executedAt: input.executedAt ?? new Date(),
      notes: input.notes?.trim() || undefined,
    };

    return this.repository.createTrade(record);
  }

  public async listTrades(): Promise<Trade[]> {
    const trades = await this.repository.listTrades();
    return [...trades].sort((a, b) => b.executedAt.getTime() - a.executedAt.getTime());
  }

  public async recordExternalTrade(trade: Trade): Promise<void> {
    const symbol = trade.symbol.trim().toUpperCase();
    if (!symbol) {
      throw new HttpError(400, "Trade symbol is required");
    }

    await this.repository.ensureStock({ symbol, name: symbol, createdAt: new Date() });

    const id = UUID_PATTERN.test(trade.id) ? trade.id : randomUUID();

    await this.repository.createTradeIfMissing({
      id,
      symbol,
      side: trade.side,
      quantity: Math.round(trade.quantity),
      price: Number(trade.price),
      executedAt: trade.executedAt,
      notes: trade.notes,
    });
  }

  public async getSnapshot(): Promise<PortfolioSnapshot> {
    const trades = await this.repository.listTrades();
    const [summaries, latestPrices] = await Promise.all([
      this.getTradeSummaries(trades),
      this.getLatestTradePrices(trades),
    ]);

    const positions: PortfolioPositionSnapshot[] = summaries.map((summary) => {
      const markPrice = latestPrices.get(summary.symbol) ?? summary.averageEntryPrice;
      const unrealizedPnl = summary.netQuantity * (markPrice - summary.averageEntryPrice);
      return {
        ...summary,
        unrealizedPnl: Number(unrealizedPnl.toFixed(2)),
      } satisfies PortfolioPositionSnapshot;
    });

    return {
      generatedAt: new Date(),
      positions,
      totalTrades: trades.length,
    } satisfies PortfolioSnapshot;
  }

  public async getTradeSummaries(tradesOverride?: Trade[]): Promise<TradeSummary[]> {
    const trades = tradesOverride ?? (await this.repository.listTrades());
    const stocks = await this.repository.listStocks();
    const stockMap = new Map(stocks.map((stock) => [stock.symbol, stock.name]));

    const states = new Map<string, PositionState>();

    for (const trade of trades) {
      const state = states.get(trade.symbol) ?? { netQuantity: 0, totalCost: 0, realizedPnl: 0 };

      if (trade.side === "BUY") {
        let remainingQuantity = trade.quantity;

        const openShortQuantity = Math.max(-state.netQuantity, 0);
        if (openShortQuantity > 0) {
          const closingQuantity = Math.min(openShortQuantity, remainingQuantity);
          if (closingQuantity > 0) {
            const entryAverage = state.netQuantity !== 0 ? state.totalCost / state.netQuantity : 0;
            state.realizedPnl += closingQuantity * (entryAverage - trade.price);
            state.netQuantity += closingQuantity;
            state.totalCost += entryAverage * closingQuantity;
            remainingQuantity -= closingQuantity;

            if (state.netQuantity === 0) {
              state.totalCost = 0;
            }
          }
        }

        if (remainingQuantity > 0) {
          state.totalCost += trade.price * remainingQuantity;
          state.netQuantity += remainingQuantity;
        }
      } else {
        const closingQty = Math.min(Math.max(state.netQuantity, 0), trade.quantity);
        const avgCost = state.netQuantity > 0 ? state.totalCost / state.netQuantity : 0;
        if (closingQty > 0) {
          state.realizedPnl += closingQty * (trade.price - avgCost);
          state.totalCost -= closingQty * avgCost;
          state.netQuantity -= closingQty;
        }

        const residualQty = trade.quantity - closingQty;
        if (residualQty > 0) {
          state.netQuantity -= residualQty;
          state.totalCost -= residualQty * trade.price;
        }
      }

      if (state.netQuantity === 0) {
        state.totalCost = 0;
      }

      states.set(trade.symbol, state);
    }

    return Array.from(states.entries()).map(([symbol, state]) => {
      const position = state.netQuantity > 0 ? "LONG" : state.netQuantity < 0 ? "SHORT" : "FLAT";
      const averageEntryPrice = state.netQuantity !== 0 ? Math.abs(state.totalCost / state.netQuantity) : 0;

      return {
        symbol,
        name: stockMap.get(symbol) ?? symbol,
        netQuantity: state.netQuantity,
        averageEntryPrice: Number(averageEntryPrice.toFixed(4)),
        realizedPnl: Number(state.realizedPnl.toFixed(2)),
        position,
      } satisfies TradeSummary;
    });
  }

  private async getLatestTradePrices(tradesOverride?: Trade[]): Promise<Map<string, number>> {
    const trades = tradesOverride ?? (await this.repository.listTrades());
    const latest = new Map<string, number>();

    for (let index = trades.length - 1; index >= 0; index -= 1) {
      const trade = trades[index];
      if (!latest.has(trade.symbol)) {
        latest.set(trade.symbol, trade.price);
      }
    }

    return latest;
  }

  /**
   * Calculate realized P&L for a specific time period.
   * If fromDate is provided, only includes P&L from trades executed on or after that date.
   * Requires processing full trade history to determine accurate cost basis.
   */
  public async getRealizedPnl(fromDate?: Date): Promise<number> {
    const trades = await this.listTrades(); // Already sorted descending, need ascending for replay
    // Sort ascending for chronological processing
    const chronologicalTrades = [...trades].sort((a, b) => a.executedAt.getTime() - b.executedAt.getTime());

    const states = new Map<string, PositionState>();
    let totalRealizedPnl = 0;

    for (const trade of chronologicalTrades) {
      const state = states.get(trade.symbol) ?? { netQuantity: 0, totalCost: 0, realizedPnl: 0 };
      let tradeRealizedPnl = 0;

      if (trade.side === "BUY") {
        let remainingQuantity = trade.quantity;

        const openShortQuantity = Math.max(-state.netQuantity, 0);
        if (openShortQuantity > 0) {
          // Covering short position
          const closingQuantity = Math.min(openShortQuantity, remainingQuantity);
          if (closingQuantity > 0) {
            const entryAverage = state.netQuantity !== 0 ? state.totalCost / state.netQuantity : 0;
            // Short P&L: (Entry Price - Exit Price) * Quantity
            const pnl = closingQuantity * (entryAverage - trade.price);
            state.realizedPnl += pnl;
            tradeRealizedPnl += pnl;

            state.netQuantity += closingQuantity;
            state.totalCost += entryAverage * closingQuantity; // reducing the negative cost basis
            remainingQuantity -= closingQuantity;

            if (state.netQuantity === 0) {
              state.totalCost = 0;
            }
          }
        }

        if (remainingQuantity > 0) {
          // Opening/Adding long
          state.totalCost += trade.price * remainingQuantity;
          state.netQuantity += remainingQuantity;
        }
      } else {
        // SELL
        const closingQty = Math.min(Math.max(state.netQuantity, 0), trade.quantity);
        const avgCost = state.netQuantity > 0 ? state.totalCost / state.netQuantity : 0;

        if (closingQty > 0) {
          // Closing long P&L: (Exit Price - Entry Price) * Quantity
          const pnl = closingQty * (trade.price - avgCost);
          state.realizedPnl += pnl;
          tradeRealizedPnl += pnl;

          state.totalCost -= closingQty * avgCost;
          state.netQuantity -= closingQty;
        }

        // Remaining sells become short positions
        const residualQty = trade.quantity - closingQty;
        if (residualQty > 0) {
          state.netQuantity -= residualQty;
          state.totalCost -= residualQty * trade.price;
        }
      }

      if (state.netQuantity === 0) {
        state.totalCost = 0;
      }

      states.set(trade.symbol, state);

      // Accumulate if within date range
      if (!fromDate || trade.executedAt >= fromDate) {
        totalRealizedPnl += tradeRealizedPnl;
      }
    }

    return Number(totalRealizedPnl.toFixed(2));
  }
}

export default PortfolioService;

import { promises as fs } from "node:fs";
import path from "node:path";
import { open, type Database } from "lmdb";
import type { Stock, Trade, TradeSide } from "../types";
import { seedStocks, seedTrades } from "../data/seed";
import type {
  CreateStockRecord,
  CreateTradeRecord,
  PortfolioRepository,
} from "./PortfolioRepository";
import { RepositoryConflictError } from "./errors";
import { deterministicTradeId } from "./storeUtils";

interface StockRecordData {
  symbol: string;
  name: string;
  createdAt: string;
}

interface TradeRecordData {
  id: string;
  symbol: string;
  side: TradeSide;
  quantity: number;
  price: number;
  executedAt: string;
  notes?: string;
}

export class LmdbPortfolioRepository implements PortfolioRepository {
  private stocksDb: Database<StockRecordData> | null = null;

  private tradesDb: Database<TradeRecordData> | null = null;

  constructor(private readonly storePath: string) { }

  /**
   * Creates a timestamped backup of the LMDB database
   * Keeps only the last 7 backups to prevent disk space issues
   * @returns Path to the created backup directory
   */
  async createBackup(): Promise<string> {
    // Include milliseconds and add random suffix to ensure unique backup names
    const timestamp = new Date().toISOString().replace(/:/g, '-').replace(/\./g, '-');
    const randomSuffix = Math.random().toString(36).substring(2, 8);
    const backupDir = path.join(path.dirname(this.storePath), 'backups');
    const backupPath = path.join(backupDir, `portfolio-${timestamp}-${randomSuffix}`);

    await fs.mkdir(backupDir, { recursive: true });

    await fs.mkdir(backupDir, { recursive: true });

    await fs.cp(this.storePath, backupPath, { recursive: true });

    await this.cleanupOldBackups(backupDir, 7);

    return backupPath;
  }

  /**
   * Restores the database from a backup
   * @param backupPath Path to the backup directory
   */
  async restoreFromBackup(backupPath: string): Promise<void> {
    try {
      await fs.access(backupPath);
    } catch {
      throw new Error(`Backup not found: ${backupPath}`);
    }

    if (this.stocksDb) {
      this.stocksDb.close();
      this.stocksDb = null;
    }
    if (this.tradesDb) {
      this.tradesDb.close();
      this.tradesDb = null;
    }

    await fs.rm(this.storePath, { recursive: true, force: true });

    await fs.rm(this.storePath, { recursive: true, force: true });

    await fs.cp(backupPath, this.storePath, { recursive: true });

    await this.initialize();
  }

  /**
   * Lists all available backups
   * @returns Array of backup paths sorted by date (newest first)
   */
  async listBackups(): Promise<string[]> {
    const backupDir = path.join(path.dirname(this.storePath), 'backups');

    try {
      const entries = await fs.readdir(backupDir);
      const backups = entries
        .filter(name => name.startsWith('portfolio-'))
        .sort()
        .reverse(); // Newest first

      return backups.map(name => path.join(backupDir, name));
    } catch {
      return []; // No backups directory yet
    }
  }

  /**
   * Exports database contents to JSON format for human inspection
   * @returns JSON object with all stocks and trades
   */
  async exportToJson(): Promise<{ stocks: Stock[]; trades: Trade[]; exportedAt: string }> {
    const stocks = await this.listStocks();
    const trades = await this.listTrades();

    return {
      stocks,
      trades,
      exportedAt: new Date().toISOString(),
    };
  }

  /**
   * Gets database statistics including backup information
   */
  async getStats(): Promise<{
    path: string;
    sizeMB: number;
    stockCount: number;
    tradeCount: number;
    backupCount: number;
    lastBackup: string | null;
  }> {
    const dataFilePath = path.join(this.storePath, 'data.mdb');

    try {
      const stats = await fs.stat(dataFilePath);
      const stocks = await this.listStocks();
      const trades = await this.listTrades();
      const backups = await this.listBackups();

      return {
        path: this.storePath,
        sizeMB: Math.round((stats.size / 1024 / 1024) * 100) / 100,
        stockCount: stocks.length,
        tradeCount: trades.length,
        backupCount: backups.length,
        lastBackup: backups.length > 0 ? path.basename(backups[0]) : null,
      };
    } catch {
      return {
        path: this.storePath,
        sizeMB: 0,
        stockCount: 0,
        tradeCount: 0,
        backupCount: 0,
        lastBackup: null,
      };
    }
  }

  private async cleanupOldBackups(backupDir: string, keepCount: number): Promise<void> {
    try {
      const entries = await fs.readdir(backupDir);
      const backups = entries
        .filter(name => name.startsWith('portfolio-'))
        .sort();

      // Remove oldest backups if we exceed keepCount
      if (backups.length > keepCount) {
        const toRemove = backups.slice(0, backups.length - keepCount);
        for (const backup of toRemove) {
          await fs.rm(path.join(backupDir, backup), { recursive: true });
        }
      }
    } catch {
      // Ignore errors in cleanup
    }
  }

  async initialize(): Promise<void> {
    if (this.stocksDb && this.tradesDb) {
      return;
    }

    const directory = path.dirname(this.storePath);
    await fs.mkdir(directory, { recursive: true });

    // Ensure storePath is not a file before trying to create it as a directory
    try {
      const stats = await fs.stat(this.storePath);
      if (stats.isFile()) {
        throw new Error(`Cannot initialize LMDB at ${this.storePath} because a file already exists at this path.`);
      }
    } catch (error) {
      if (error instanceof Error && 'code' in error && error.code !== 'ENOENT') {
        throw error;
      }
    }

    await fs.mkdir(this.storePath, { recursive: true });

    const root = open<unknown>({
      path: this.storePath,
      compression: true,
    });

    const stocksDb = root.openDB<StockRecordData>({
      name: "stocks",
      encoding: "json",
    });
    const tradesDb = root.openDB<TradeRecordData>({
      name: "trades",
      encoding: "json",
    });

    this.stocksDb = stocksDb;
    this.tradesDb = tradesDb;

    if (this.shouldSeed()) {
      await this.seed();
    }
  }

  async reset(): Promise<void> {
    await this.seed();
  }

  async listStocks(): Promise<Stock[]> {
    const stocksDb = this.ensureStocksDb();
    const stocks: Stock[] = [];

    for (const { value } of stocksDb.getRange()) {
      stocks.push(this.toStock(value));
    }

    return stocks.sort((a, b) => a.symbol.localeCompare(b.symbol));
  }

  async findStock(symbol: string): Promise<Stock | undefined> {
    const stocksDb = this.ensureStocksDb();
    const record = stocksDb.get(symbol.toUpperCase());
    return record ? this.toStock(record) : undefined;
  }

  async createStock(record: CreateStockRecord): Promise<Stock> {
    const stocksDb = this.ensureStocksDb();
    const symbol = record.symbol.toUpperCase();
    const existing = stocksDb.get(symbol);
    if (existing) {
      throw new RepositoryConflictError(`Stock ${symbol} already exists`);
    }

    const entry: StockRecordData = {
      symbol,
      name: record.name,
      createdAt: record.createdAt.toISOString(),
    };

    await stocksDb.put(symbol, entry);
    return this.toStock(entry);
  }

  async ensureStock(record: CreateStockRecord): Promise<Stock> {
    const existing = await this.findStock(record.symbol);
    if (existing) {
      return existing;
    }
    return this.createStock(record);
  }

  async listTrades(): Promise<Trade[]> {
    const tradesDb = this.ensureTradesDb();
    const trades: Trade[] = [];

    for (const { value } of tradesDb.getRange()) {
      trades.push(this.toTrade(value));
    }

    return trades.sort((a, b) => {
      const diff = a.executedAt.getTime() - b.executedAt.getTime();
      if (diff !== 0) {
        return diff;
      }
      return a.id.localeCompare(b.id);
    });
  }

  async createTrade(record: CreateTradeRecord): Promise<Trade> {
    const tradesDb = this.ensureTradesDb();
    const existing = tradesDb.get(record.id);
    if (existing) {
      throw new RepositoryConflictError(`Trade ${record.id} already exists`);
    }

    const entry: TradeRecordData = this.toTradeRecord(record);
    await tradesDb.put(entry.id, entry);
    return this.toTrade(entry);
  }

  async createTradeIfMissing(record: CreateTradeRecord): Promise<boolean> {
    const tradesDb = this.ensureTradesDb();
    const existing = tradesDb.get(record.id);
    if (existing) {
      return false;
    }

    const entry: TradeRecordData = this.toTradeRecord(record);
    await tradesDb.put(entry.id, entry);
    return true;
  }

  private ensureStocksDb(): Database<StockRecordData> {
    if (!this.stocksDb) {
      throw new Error("Stocks database is not initialised");
    }
    return this.stocksDb;
  }

  private ensureTradesDb(): Database<TradeRecordData> {
    if (!this.tradesDb) {
      throw new Error("Trades database is not initialised");
    }
    return this.tradesDb;
  }

  private shouldSeed(): boolean {
    const stocksDb = this.ensureStocksDb();
    const iterator = stocksDb.getRange({ limit: 1 })[Symbol.iterator]();
    const first = iterator.next();
    return Boolean(first.done);
  }

  private async seed(): Promise<void> {
    const stocksDb = this.ensureStocksDb();
    const tradesDb = this.ensureTradesDb();

    const seededStocks: StockRecordData[] = seedStocks.map((stock) => ({
      symbol: stock.symbol.toUpperCase(),
      name: stock.name.trim(),
      createdAt: new Date().toISOString(),
    }));

    const seededTrades: TradeRecordData[] = seedTrades.map((trade) => ({
      id: deterministicTradeId({
        symbol: trade.symbol.toUpperCase(),
        side: trade.side,
        quantity: trade.quantity,
        price: trade.price,
        executedAt: trade.executedAt ?? new Date(),
        notes: trade.notes,
      }),
      symbol: trade.symbol.toUpperCase(),
      side: trade.side,
      quantity: Math.round(trade.quantity),
      price: trade.price,
      executedAt: (trade.executedAt ?? new Date()).toISOString(),
      notes: trade.notes,
    }));

    stocksDb.clearSync();
    tradesDb.clearSync();

    for (const entry of seededStocks) {
      await stocksDb.put(entry.symbol, entry);
    }

    const sortedTrades = seededTrades
      .sort((a, b) => new Date(a.executedAt).getTime() - new Date(b.executedAt).getTime());

    for (const entry of sortedTrades) {
      await tradesDb.put(entry.id, entry);
    }
  }

  private toStock(record: StockRecordData): Stock {
    return {
      symbol: record.symbol,
      name: record.name,
      createdAt: new Date(record.createdAt),
    };
  }

  private toTrade(record: TradeRecordData): Trade {
    return {
      id: record.id,
      symbol: record.symbol,
      side: record.side,
      quantity: record.quantity,
      price: record.price,
      executedAt: new Date(record.executedAt),
      notes: record.notes,
    };
  }

  private toTradeRecord(record: CreateTradeRecord): TradeRecordData {
    return {
      id: record.id,
      symbol: record.symbol.toUpperCase(),
      side: record.side,
      quantity: Math.round(record.quantity),
      price: Number(record.price),
      executedAt: record.executedAt.toISOString(),
      notes: record.notes,
    };
  }
}

